-- Esquema mínimo con los MISMOS nombres de columna que las entidades (ver *.entity.ts).
-- Si una entidad cambia una columna usada por la analítica, actualizar aquí.
CREATE TABLE productos (producto_id serial PRIMARY KEY, producto_nombre text UNIQUE, descripcion text, activo boolean DEFAULT true, emoji text, personalizacion text, categoria varchar(20), sabor_grupo_id int);
CREATE TABLE producto_variantes (variante_id serial PRIMARY KEY, producto_id int REFERENCES productos(producto_id), nombre text, precio numeric, descripcion text, precio_leche numeric, stock_bebida int DEFAULT 0, categoria_bebida varchar(30), alerta_bebida int, nivel_objetivo_bebida int, activo boolean DEFAULT true);
CREATE TABLE sabor_grupos (id serial PRIMARY KEY, nombre varchar(60) UNIQUE, orden int DEFAULT 0);
CREATE TABLE pizza_sabores (sabor_id serial PRIMARY KEY, nombre text, tipo text DEFAULT 'tradicional', grupo_id int REFERENCES sabor_grupos(id), recargo_pequena numeric DEFAULT 0, recargo_mediana numeric DEFAULT 0, recargo_grande numeric DEFAULT 0, activo boolean DEFAULT true);
CREATE TABLE facturas_ventas (factura_id serial PRIMARY KEY, cliente_nombre text, telefono_cliente text, descripcion text, "fechaFactura" timestamptz DEFAULT now(), estado text DEFAULT 'pendiente', metodo text, pago_efectivo numeric, pago_transferencia numeric, total numeric, usuario_cobro_id text, fecha_cobro timestamptz, monto_pagado numeric, cuenta_transferencia_id int, cuenta_transferencia_nombre text, desglose_transferencia jsonb);
CREATE TABLE ordenes (orden_id serial PRIMARY KEY, factura_id int REFERENCES facturas_ventas(factura_id) ON DELETE CASCADE, tipo_pedido text DEFAULT 'mesa', estado_orden text DEFAULT 'pendiente', fecha_orden timestamptz DEFAULT now(), observaciones text, canal varchar(20), usuario_creacion_id text);
CREATE TABLE ordenes_productos (id bigserial PRIMARY KEY, orden_id int REFERENCES ordenes(orden_id) ON DELETE CASCADE, producto text, cantidad numeric, precio_unitario numeric, variante_id int REFERENCES producto_variantes(variante_id), base text, "productoObjProductoId" int REFERENCES productos(producto_id), producto_base text, variante_nombre text, tamano varchar(20), categoria varchar(20), precio_lista numeric, precio_manual boolean, detalle_version varchar(20));
CREATE TABLE ordenes_productos_sabores (id bigserial PRIMARY KEY, orden_producto_id bigint REFERENCES ordenes_productos(id) ON DELETE CASCADE, sabor_id int REFERENCES pizza_sabores(sabor_id) ON DELETE SET NULL, sabor_nombre text, posicion smallint, fraccion numeric(6,4));
CREATE TABLE domiciliarios (telefono text PRIMARY KEY, domiciliario_nombre text);
CREATE TABLE domicilios (domicilio_id serial PRIMARY KEY, fecha_creado timestamptz DEFAULT now(), factura_id int, orden_id int, telefono text, telefono_domiciliario_asignado text, direccion_entrega text, costo_domicilio numeric, estado_domicilio text DEFAULT 'pendiente');
CREATE TABLE users (id uuid PRIMARY KEY, username text, name text);
CREATE TABLE facturas_pagos (pagos_id bigserial PRIMARY KEY, total numeric, nombre_gasto text, descripcion text, estado text, fecha_factura date, metodo text, categoria text, tipo_gasto text, cuenta_origen_id int);
CREATE TABLE cuentas_transferencia (id serial PRIMARY KEY, nombre text, activa boolean DEFAULT true);
CREATE TABLE migraciones_datos (id varchar(100) PRIMARY KEY, estado varchar(20), ejecutada_en timestamptz, resultado jsonb, actualizada_en timestamptz DEFAULT now());
